import { useCallback, useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { supabase, isConfigured } from './lib/supabase';
import type { PdfDocument } from './lib/pdf';
import {
  Activity, ArrowDownLeft, ArrowUpRight, Bell, BriefcaseBusiness, CalendarDays,
  ChartNoAxesCombined, Check, CircleDollarSign, ClipboardList,
  Download, FileText, Globe2, LayoutDashboard, LogOut, Menu, Plus, Printer,
  Search, Settings, ShieldCheck, Users, Wallet, X,
} from 'lucide-react';

type Page = 'Tableau de bord'|'Devis'|'Factures'|'Missions'|'Dépenses'|'Trésorerie'|'Clients'|'Prestataires'|'Catalogue'|'Charges'|'Rapports'|'Paramètres';
type Row = Record<string, any> & { id?: string | number };
type Line = { service_id:string; description:string; quantity:number; unit:string; unit_price:number; service_fee:number; currency:string; exchange_rate:number };
const nav:{name:Page;icon:any}[]=[
  {name:'Tableau de bord',icon:LayoutDashboard},{name:'Devis',icon:ClipboardList},{name:'Factures',icon:FileText},
  {name:'Missions',icon:BriefcaseBusiness},{name:'Dépenses',icon:ArrowUpRight},{name:'Trésorerie',icon:Wallet},
  {name:'Clients',icon:Users},{name:'Prestataires',icon:Globe2},{name:'Catalogue',icon:Activity},
  {name:'Charges',icon:CalendarDays},{name:'Rapports',icon:ChartNoAxesCombined},
];
const tableByPage:Partial<Record<Page,string>>={Clients:'clients',Devis:'quotes',Factures:'invoices',Missions:'missions',Dépenses:'expenses',Trésorerie:'payments',Prestataires:'suppliers',Catalogue:'catalogue_services',Charges:'recurring_charges'};
const categories=['Hébergement','Transport terrestre','Billets d’avion','Transport maritime','Restauration','Guides touristiques','Excursions et activités','Taxes et autorisations','Communication','Autres dépenses'];
const euroRate=492;
const clauseDefault='Le présent devis couvre exclusivement les prestations et services qui y sont expressément mentionnés. Toute prestation supplémentaire, activité additionnelle, modification du programme, prolongation de séjour ou demande particulière formulée par le client après validation du devis initial fera l’objet d’une facturation complémentaire. Le montant de ces prestations supplémentaires sera communiqué au client avant leur réalisation et soumis à son accord préalable. Les frais correspondants seront ajoutés au montant initial et feront l’objet d’une facture complémentaire ou d’une régularisation de la facture existante. Toute dépense exceptionnelle non prévue dans le devis initial et imputable au client devra également lui être communiquée et justifiée.';
const money=(n:number,c='KMF')=>`${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(n||0))} ${c}`;
const ref=(prefix:string)=>`${prefix}-${new Date().getFullYear()}-${Date.now().toString().slice(-6)}`;
const today=()=>new Date().toISOString().slice(0,10);

export default function App(){
  const [session,setSession]=useState<any>(null); const [profile,setProfile]=useState<Row|null>(null);
  const [page,setPage]=useState<Page>('Tableau de bord'); const [rows,setRows]=useState<Row[]>([]); const [all,setAll]=useState<Record<string,Row[]>>({});
  const [loading,setLoading]=useState(false); const [notice,setNotice]=useState(''); const [authBusy,setAuthBusy]=useState(false); const [upgradePending,setUpgradePending]=useState(false);
  const [mobile,setMobile]=useState(false); const [modal,setModal]=useState<'record'|'quote'|'supplement'|'payment'|'settings'|null>(null);
  const [editing,setEditing]=useState<Row|null>(null); const [selected,setSelected]=useState<Row|null>(null); const [search,setSearch]=useState('');
  const [lines,setLines]=useState<Line[]>([{service_id:'',description:'',quantity:1,unit:'Prestation',unit_price:0,service_fee:0,currency:'KMF',exchange_rate:1}]);
  const [period,setPeriod]=useState('month'); const [reportRows,setReportRows]=useState<Row[]>([]); const [auditRows,setAuditRows]=useState<Row[]>([]); const [settings,setSettings]=useState<Row>({company_name:'Agence ComTour',address:'Moroni, Grande Comore, Union des Comores',phone:'',email:'',eur_to_kmf:euroRate,service_clause:clauseDefault});

  useEffect(()=>{if(!supabase)return; supabase.auth.getSession().then(({data})=>setSession(data.session)); const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>setSession(s)); return()=>subscription.unsubscribe()},[]);
  useEffect(()=>{if(!session||!supabase)return; let ok=true; supabase.from('profiles').select('*').eq('id',session.user.id).maybeSingle().then(({data})=>{if(ok)setProfile(data as Row|null)}); return()=>{ok=false}},[session]);
  const role=profile?.role||'agent';
  const load=useCallback(async()=>{
    if(!session||!supabase)return;
    setLoading(true);
    const requests=Object.entries({clients:'clients',quotes:'quotes',invoices:'invoices',missions:'missions',expenses:'expenses',payments:'payments',suppliers:'suppliers',catalogue_services:'catalogue_services',recurring_charges:'recurring_charges'}).map(async([k,t])=>{
      const {data,error}=await supabase!.from(t).select('*').order('created_at',{ascending:false}).limit(1000);
      if(error && !['recurring_charges'].includes(t)) throw error;
      return [k,(data||[]) as Row[]] as const;
    });
    try{const values=await Promise.all(requests); if(!ok())return; const next=Object.fromEntries(values); setAll(next); const table=tableByPage[page]; setRows(table?next[table]||[]:[]);
      const {data:s}=await supabase.from('company_settings').select('*').eq('id',1).maybeSingle(); if(s)setSettings(s as Row);
      const {error:featureError}=await supabase.from('quote_items').select('id').limit(1);setUpgradePending(Boolean(featureError));
      if(page==='Charges' && ['admin','comptable'].includes(role)){const {data:generated,error}=await supabase.rpc('generate_monthly_charges',{p_month:`${today().slice(0,7)}-01`});if(error)setNotice(error.message);else if(Number(generated)>0){const {data:expenses}=await supabase.from('expenses').select('*').order('created_at',{ascending:false}).limit(1000);setAll(current=>({...current,expenses:(expenses||[]) as Row[]}));}}
    }catch(e:any){setNotice(e.message||'Impossible de charger les données.')}finally{if(ok())setLoading(false)}
    function ok(){return true}
  },[session,page,role]);
  useEffect(()=>{load()},[load]);
  useEffect(()=>{if(!session||!supabase||page!=='Rapports')return; let live=true; supabase.from('mission_financial_summary').select('*').then(({data,error})=>{if(live){if(error)setNotice('Applique la migration financière Supabase pour activer le rapport détaillé.');setReportRows((data||[]) as Row[])}});if(['admin','comptable'].includes(role))supabase.from('audit_log').select('*').order('occurred_at',{ascending:false}).limit(100).then(({data,error})=>{if(live){if(error)setNotice(`Journal indisponible : ${error.message}`);setAuditRows((data||[]) as Row[])}});return()=>{live=false}},[session,page,role]);
  const filtered=useMemo(()=>rows.filter(r=>Object.values(r).some(v=>String(v??'').toLowerCase().includes(search.toLowerCase()))),[rows,search]);
  const totals=useMemo(()=>({invoices:(all.invoices||[]).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1),0),payments:(all.payments||[]).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1)*(r.kind==='remboursement'?-1:r.kind==='paiement_fournisseur'?-1:r.kind==='encaissement'||r.kind==='avance_client'?1:0),0),expenses:(all.expenses||[]).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1),0),cash:(all.payments||[]).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1)*(r.kind==='remboursement'||r.kind==='paiement_fournisseur'?-1:1),0)-(all.expenses||[]).filter(r=>r.is_paid!==false).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1),0)}),[all]);
  const periodStart=useMemo(()=>{const d=new Date();d.setHours(0,0,0,0);if(period==='day')return d;if(period==='week'){const weekday=(d.getDay()+6)%7;d.setDate(d.getDate()-weekday);return d}if(period==='quarter'){d.setMonth(Math.floor(d.getMonth()/3)*3,1);return d}if(period==='year'){d.setMonth(0,1);return d}d.setDate(1);return d},[period]);
  const inPeriod=(value:string|undefined)=>Boolean(value&&new Date(value)>=periodStart);
  const periodTotals={invoices:invoicesForPeriod(),payments:paymentsForPeriod(),expenses:expensesForPeriod()};
  function invoicesForPeriod(){return (all.invoices||[]).filter(r=>inPeriod(r.created_at)).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1),0)}
  function paymentsForPeriod(){return (all.payments||[]).filter(r=>inPeriod(r.paid_at)&&(r.kind==='encaissement'||r.kind==='avance_client'||r.kind==='remboursement')).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1)*(r.kind==='remboursement'?-1:1),0)}
  function expensesForPeriod(){return (all.expenses||[]).filter(r=>inPeriod(r.paid_at)).reduce((s,r)=>s+Number(r.amount||0)*Number(r.exchange_rate||1),0)}
  const monthlySeries=useMemo(()=>Array.from({length:6},(_,idx)=>{const date=new Date();date.setDate(1);date.setMonth(date.getMonth()-(5-idx));const key=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`;const sum=(rs:Row[],field:string)=>rs.filter(r=>String(r[field]||'').slice(0,7)===key).reduce((n,r)=>n+Number(r.amount||0)*Number(r.exchange_rate||1),0);return {label:date.toLocaleDateString('fr-FR',{month:'short'}),invoices:sum(all.invoices||[],'created_at'),payments:sum((all.payments||[]).filter(r=>['encaissement','avance_client'].includes(r.kind)),'paid_at'),expenses:sum((all.expenses||[]).filter(r=>r.is_paid!==false),'paid_at')}}),[all]);
  const chartMax=Math.max(1,...monthlySeries.flatMap(m=>[m.invoices,m.payments,m.expenses]));

  async function login(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;setAuthBusy(true);const fd=new FormData(e.currentTarget);const {error}=await supabase.auth.signInWithPassword({email:String(fd.get('email')),password:String(fd.get('password'))});if(error)setNotice(error.message);setAuthBusy(false)}
  async function saveRecord(e:FormEvent<HTMLFormElement>){e.preventDefault();const table=tableByPage[page];if(!supabase||!table)return;const fd=new FormData(e.currentTarget);const body:Record<string,any>=Object.fromEntries(fd);const receipt=fd.get('receipt_file');delete body.receipt_file;if(receipt instanceof File&&receipt.size){const safe=receipt.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`${session.user.id}/expenses/${Date.now()}-${safe}`;const {error:uploadError}=await supabase.storage.from('comtour-documents').upload(path,receipt,{contentType:receipt.type,upsert:false});if(uploadError){setNotice(`Justificatif non envoyé : ${uploadError.message}`);return}body.receipt_path=path}for(const key of ['amount','price','exchange_rate','due_day'])if(body[key]!==undefined&&body[key]!=='')body[key]=Number(body[key]);if(body.is_paid!==undefined)body.is_paid=body.is_paid==='true';for(const [k,v] of Object.entries(body))if(v==='')body[k]=null;
    if(['Devis','Factures','Missions'].includes(page)&&!body.reference)body.reference=ref(page==='Devis'?'DEV':page==='Factures'?'FAC':'MIS');
    if(['Devis','Factures','Dépenses','Trésorerie','Charges'].includes(page)){body.currency=body.currency||'KMF';body.exchange_rate=body.currency==='KMF'?1:Number(settings.eur_to_kmf||euroRate)}
    if(page==='Dépenses'||page==='Trésorerie')body.paid_at=body.paid_at||today();
    const q=editing?supabase.from(table).update(body).eq('id',editing.id):supabase.from(table).insert(body);const {error}=await q;
    if(error)setNotice(`Enregistrement impossible : ${error.message}`);else{setNotice(editing?'Modification enregistrée.':'Enregistrement créé.');setModal(null);setEditing(null);await load()}
  }
  async function saveQuote(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;const fd=new FormData(e.currentTarget);const currency=String(fd.get('currency')||'KMF');const quote={reference:ref('DEV'),title:String(fd.get('title')),client_id:String(fd.get('client_id')),status:'brouillon',currency,exchange_rate:currency==='KMF'?1:Number(settings.eur_to_kmf||euroRate),deposit_percent:Number(fd.get('deposit_percent')||50),service_clause:String(settings.service_clause||clauseDefault)};
    if(lines.some(l=>!l.description.trim()||l.unit_price<0||l.quantity<=0)){setNotice('Complète chaque ligne du devis avant l’enregistrement.');return}
    const {data,error}=await supabase.rpc('create_quote_with_items',{p_quote:quote,p_items:lines});if(error){setNotice(`Enregistrement impossible : ${error.message}`);return}setNotice(`Devis ${quote.reference} créé.`);setModal(null);setLines([{service_id:'',description:'',quantity:1,unit:'Prestation',unit_price:0,service_fee:0,currency:quote.currency,exchange_rate:quote.exchange_rate}]);await load();setSelected((all.quotes||[]).find(x=>x.id===data)||null);
  }
  async function updateQuoteStatus(q:Row,status:string){if(!supabase)return;if(status==='validé'&&!window.confirm('Confirme que le client a bien accepté ce devis. Cette validation fige le devis initial et ne pourra plus être modifiée.'))return;const {error}=await supabase.from('quotes').update({status,...(status==='validé'?{accepted_at:new Date().toISOString(),accepted_by:session.user.email}:{})}).eq('id',q.id);if(error)setNotice(error.message);else{setNotice(status==='validé'?'Validation du devis enregistrée.':'Statut du devis mis à jour.');await load()}}
  async function invoiceFromQuote(q:Row,kind='standard'){if(!supabase)return;if(q.status!=='validé'){setNotice('Valide le devis après l’accord du client avant de créer une facture.');return}if((all.invoices||[]).some(i=>i.quote_id===q.id&&i.kind===kind)){setNotice(`Une facture de type ${kind} existe déjà pour ce devis.`);return}const percent=Number(q.deposit_percent||50);const amount=kind==='acompte'?Number(q.amount)*percent/100:kind==='solde'?Number(q.amount)*(100-percent)/100:Number(q.amount);const {error}=await supabase.from('invoices').insert({reference:ref('FAC'),quote_id:q.id,client_id:q.client_id,status:'impayee',kind,description:q.title, currency:q.currency,exchange_rate:q.exchange_rate,amount,service_clause:q.service_clause});if(error)setNotice(error.message);else{setNotice(`Facture ${kind} créée à partir du devis.`);setPage('Factures');await load()}}
  async function missionFromQuote(q:Row){if(!supabase)return;if(q.status!=='validé'){setNotice('Valide le devis après l’accord du client avant de créer une mission.');return}if((all.missions||[]).some(m=>m.quote_id===q.id)){setNotice('Une mission existe déjà pour ce devis.');return}const {error}=await supabase.from('missions').insert({reference:ref('MIS'),quote_id:q.id,client_id:q.client_id,status:'en_preparation'});if(error)setNotice(error.message);else{setNotice('Dossier de mission créé depuis le devis.');setPage('Missions');await load()}}
  async function savePayment(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;const fd=new FormData(e.currentTarget);const currency=String(fd.get('currency')),kind=String(fd.get('kind'));const body={invoice_id:fd.get('invoice_id')||null,mission_id:fd.get('mission_id')||null,supplier_id:fd.get('supplier_id')||null,kind,amount:Number(fd.get('amount')),currency,exchange_rate:currency==='KMF'?1:Number(settings.eur_to_kmf||euroRate),paid_at:String(fd.get('paid_at')||today()),method:String(fd.get('method')||''),receipt_reference:kind==='paiement_fournisseur'?null:ref('REC')};const {error}=await supabase.from('payments').insert(body);if(error)setNotice(error.message);else{setNotice(kind==='paiement_fournisseur'?'Paiement fournisseur enregistré.':`Paiement enregistré · reçu ${body.receipt_reference}`);setModal(null);await load();if(kind!=='paiement_fournisseur'){const {data:logo}=settings.logo_path?await supabase.storage.from('comtour-documents').createSignedUrl(settings.logo_path,180):{data:null};printReceipt(body,all.invoices?.find(i=>i.id===body.invoice_id),settings,logo?.signedUrl)}}}
  async function saveSupplement(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase||!selected)return;const fd=new FormData(e.currentTarget);const quantity=Number(fd.get('quantity')||1),price=Number(fd.get('unit_price')||0),fee=Number(fd.get('service_fee')||0),currency=String(fd.get('currency')||'KMF'),kind=String(fd.get('kind')||'supplement');const payload={mission_id:selected.id,kind,title:String(fd.get('title')),description:String(fd.get('description')||''),quantity,unit_price:price,service_fee:fee,currency,exchange_rate:currency==='KMF'?1:Number(settings.eur_to_kmf||euroRate),total:quantity*price+fee,client_status:'à_valider',reason:String(fd.get('reason')||'Modification demandée en cours de mission'),created_by:session.user.id};const {error}=await supabase.from('mission_adjustments').insert(payload);if(error)setNotice(error.message);else{setNotice('Modification enregistrée en attente de l’accord du client.');setModal(null);await loadMission(selected)}}
  async function invoiceFromSupplement(a:Row){if(!supabase||!selected)return;if(a.client_status!=='accepté'){setNotice('Un accord client doit être enregistré avant la facturation.');return}if((all.invoices||[]).some(i=>i.adjustment_id===a.id)){setNotice('Une facture complémentaire existe déjà pour ce supplément.');return}const {error}=await supabase.from('invoices').insert({reference:ref('FAC'),adjustment_id:a.id,mission_id:selected.id,quote_id:selected.quote_id,client_id:selected.client_id,status:'impayee',kind:'complementaire',description:a.title,amount:a.total,currency:a.currency,exchange_rate:a.exchange_rate,service_clause:settings.service_clause});if(error)setNotice(error.message);else{setNotice('Facture complémentaire créée.');await loadMission(selected);await load()}}
  async function setSupplementStatus(a:Row,status:'accepté'|'refusé'){if(!supabase||!selected)return;const {error}=await supabase.from('mission_adjustments').update({client_status:status,accepted_at:status==='accepté'?new Date().toISOString():null,accepted_by:status==='accepté'?session.user.email:null}).eq('id',a.id);if(error)setNotice(error.message);else{await supabase.from('mission_events').insert({mission_id:selected.id,event_type:`supplement_${status}`,description:`${a.title} : ${status} par ${session.user.email}`,amount:a.total,currency:a.currency});setNotice(status==='accepté'?'Validation du client consignée.':'Refus du client enregistré.');await loadMission(selected)}}
  async function loadMission(m:Row){if(!supabase)return;setSelected(m);const [{data:summary},{data:adjustments},{data:events},{data:expenses}]=await Promise.all([supabase.from('mission_financial_summary').select('*').eq('mission_id',m.id).maybeSingle(),supabase.from('mission_adjustments').select('*').eq('mission_id',m.id).order('created_at',{ascending:false}),supabase.from('mission_events').select('*').eq('mission_id',m.id).order('occurred_at',{ascending:false}),supabase.from('expenses').select('*').eq('mission_id',m.id).order('paid_at',{ascending:false})]);setSelected({...m,summary,adjustments:adjustments||[],events:events||[],missionExpenses:expenses||[]})}
  function openDirectoryRecord(r:Row){if(page==='Clients'){setSelected({...r,historyQuotes:quotes.filter(q=>q.client_id===r.id),historyInvoices:invoices.filter(i=>i.client_id===r.id),historyMissions:missions.filter(m=>m.client_id===r.id),historyPayments:(all.payments||[]).filter(p=>invoices.some(i=>i.id===p.invoice_id&&i.client_id===r.id)||missions.some(m=>m.id===p.mission_id&&m.client_id===r.id))})}else if(page==='Prestataires'){setSelected({...r,historyExpenses:(all.expenses||[]).filter(e=>e.supplier_id===r.id),historyPayments:(all.payments||[]).filter(p=>p.supplier_id===r.id)})}}
  async function saveSettings(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!supabase)return;const fd=new FormData(e.currentTarget);let logoPath=settings.logo_path||null;const logo=fd.get('logo_file');if(logo instanceof File&&logo.size){const path=`${session.user.id}/branding/${Date.now()}-${logo.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error:uploadError}=await supabase.storage.from('comtour-documents').upload(path,logo,{contentType:logo.type,upsert:false});if(uploadError){setNotice(`Logo non envoyé : ${uploadError.message}`);return}logoPath=path}const body={id:1,company_name:String(fd.get('company_name')),address:String(fd.get('address')),phone:String(fd.get('phone')),email:String(fd.get('email')),eur_to_kmf:Number(fd.get('eur_to_kmf')),opening_cash_kmf:Number(fd.get('opening_cash_kmf')||0),service_clause:String(fd.get('service_clause')),logo_path:logoPath,updated_by:session.user.id};const {error}=await supabase.from('company_settings').upsert(body);if(error)setNotice(error.message);else{setSettings(body as Row);setNotice('Paramètres de l’agence enregistrés.');setModal(null)}}
  async function printDocument(record:Row,kind:'DEVIS'|'FACTURE'){if(!supabase)return;const quoteId=record.kind==='complementaire'?undefined:(kind==='DEVIS'?record.id:record.quote_id);let items:Row[]=[];if(quoteId){const {data,error}=await supabase.from('quote_items').select('*').eq('quote_id',quoteId).order('created_at');if(!error)items=(data||[]) as Row[]}const client=clients.find(c=>c.id===record.client_id);const linesHtml=items.length?items.map(i=>`<tr><td>${html(i.description)}<small>${html(i.quantity)} ${html(i.unit)} × ${money(i.unit_price,i.currency)}</small></td><td>${money(i.line_total,i.currency)}</td></tr>`).join(''):`<tr><td>${html(record.title||record.description||kind)}</td><td>${money(record.amount,record.currency)}</td></tr>`;const deposit=Number(record.amount||0)*Number(record.deposit_percent||50)/100;const paid=(all.payments||[]).filter(p=>p.invoice_id===record.id).reduce((s,p)=>s+Number(p.amount||0)*Number(p.exchange_rate||1),0);const logo=settings.logo_path&&supabase?await supabase.storage.from('comtour-documents').createSignedUrl(settings.logo_path,180).then(x=>x.data?.signedUrl).catch(()=>undefined):undefined;printHtml(`${settings.company_name||'ComTour'} · ${kind} ${record.reference}`,`<header>${logo?`<img class="logo" src="${html(logo)}">`:''}<h1>${html(settings.company_name||'Agence ComTour')}</h1><p>${html(settings.address||'')} · ${html(settings.phone||'')} · ${html(settings.email||'')}</p></header><hr><h2>${kind} ${html(record.reference)}</h2><p>Émis le ${new Date(record.created_at||Date.now()).toLocaleDateString('fr-FR')} · Devise ${html(record.currency||'KMF')} · Taux appliqué ${html(record.exchange_rate||1)}</p><p><b>Client :</b> ${html(client?.full_name||'—')} · ${html(client?.email||'')} · ${html(client?.phone||'')}</p><p><b>Objet :</b> ${html(record.title||record.description||kind)}</p><table><thead><tr><th>Prestation</th><th>Montant</th></tr></thead><tbody>${linesHtml}</tbody></table><p class="total">Total : ${money(record.amount,record.currency)}</p>${kind==='DEVIS'?`<p>Acompte demandé (${Number(record.deposit_percent||50)} %) : <b>${money(deposit,record.currency)}</b></p><p>Solde : <b>${money(Number(record.amount||0)-deposit,record.currency)}</b></p>`:`<p>Déjà réglé : ${money(paid,record.currency)} · Reste à payer : ${money(Math.max(0,Number(record.amount||0)-paid),record.currency)}</p>`}<p class="terms">${html(record.service_clause||settings.service_clause||clauseDefault)}</p><footer>COMTOUR · Moroni, Union des Comores</footer>`)}
  async function makePdf(data:PdfDocument){const {downloadComTourPdf}=await import('./lib/pdf');downloadComTourPdf(data)}
  async function logoDataUrl(){if(!supabase||!settings.logo_path)return undefined;const {data,error}=await supabase.storage.from('comtour-documents').download(settings.logo_path);if(error||!data)return undefined;return new Promise<string|undefined>(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(typeof reader.result==='string'?reader.result:undefined);reader.onerror=()=>resolve(undefined);reader.readAsDataURL(data)})}
  async function downloadDocument(record:Row,kind:'DEVIS'|'FACTURE'){if(!supabase)return;const quoteId=record.kind==='complementaire'?undefined:(kind==='DEVIS'?record.id:record.quote_id);let items:Row[]=[];if(quoteId){const {data}=await supabase.from('quote_items').select('*').eq('quote_id',quoteId).order('created_at');items=(data||[]) as Row[]}const client=clients.find(c=>c.id===record.client_id);const currency=record.currency||'KMF';const total=Number(record.amount||0);const paid=(all.payments||[]).filter(p=>p.invoice_id===record.id).reduce((s,p)=>s+Number(p.amount||0)*Number(p.exchange_rate||1),0);const deposit=total*Number(record.deposit_percent||50)/100;await makePdf({title:kind==='DEVIS'?'Devis':'Facture',reference:record.reference||'COMTOUR',companyName:settings.company_name||'Agence ComTour',address:settings.address,phone:settings.phone,email:settings.email,logoData:await logoDataUrl(),clientName:client?.full_name,clientContact:[client?.email,client?.phone,client?.address].filter(Boolean).join(' · '),date:new Date(record.created_at||Date.now()).toLocaleDateString('fr-FR'),currency,exchangeRate:Number(record.exchange_rate||1),lines:items.length?items.map(i=>({description:i.description,quantity:Number(i.quantity||1),unit:i.unit,unitPrice:Number(i.unit_price||0),serviceFee:Number(i.service_fee||0),total:Number(i.line_total||0),currency:i.currency||currency})):[{description:record.title||record.description||kind,total,currency}],summary:kind==='DEVIS'?[['Montant total',money(total,currency)],[`Acompte demandé (${Number(record.deposit_percent||50)} %)`,money(deposit,currency)],['Solde restant',money(total-deposit,currency)]]:[['Montant de la facture',money(total,currency)],['Déjà réglé',money(paid,currency)],['Reste à payer',money(Math.max(0,total-paid),currency)]],clause:record.service_clause||settings.service_clause||clauseDefault,filename:`${kind}-${record.reference||'COMTOUR'}`})}
  async function downloadMissionDocument(m:Row){const s=m.summary||{};await makePdf({title:'Bilan financier de mission',reference:m.reference||'MISSION',companyName:settings.company_name||'Agence ComTour',address:settings.address,phone:settings.phone,email:settings.email,logoData:await logoDataUrl(),date:new Date().toLocaleDateString('fr-FR'),lines:(m.adjustments||[]).map((a:Row)=>({description:`${a.title} · ${a.client_status}`,quantity:Number(a.quantity||1),unit:'Prestation',unitPrice:Number(a.unit_price||a.total||0),serviceFee:Number(a.service_fee||0),total:Number(a.total||0),currency:a.currency||'KMF'})),summary:[['Devis initial',money(s.initial_quote_kmf)],['Modifications acceptées',money(s.accepted_changes_kmf)],['Montant vendu',money(s.sold_total_kmf)],['Recettes encaissées',money(s.collected_kmf)],['Reste à encaisser',money(s.receivable_kmf)],['Coûts supportés par ComTour',money(s.comtour_costs_kmf)],['Avances pour le client',money(s.client_advances_kmf)],['Résultat estimé',money(s.estimated_profit_kmf)]],filename:`Bilan-${m.reference||'mission'}`})}
  async function downloadReceipt(payment:Row,invoice?:Row){await makePdf({title:'Reçu de paiement',reference:payment.receipt_reference||'REC',companyName:settings.company_name||'Agence ComTour',address:settings.address,phone:settings.phone,email:settings.email,logoData:await logoDataUrl(),clientName:clients.find(c=>c.id===invoice?.client_id)?.full_name,date:payment.paid_at||today(),currency:payment.currency||'KMF',summary:[['Facture associée',invoice?.reference||'Paiement sans facture liée'],['Mode de paiement',payment.method||'—'],['Nature',payment.kind||'Encaissement'],['Montant reçu',money(payment.amount,payment.currency)]],filename:`Recu-${payment.receipt_reference||'ComTour'}`})}
  async function downloadReportPdf(){await makePdf({title:'Rapport de rentabilité par mission',reference:`RAP-${today()}`,companyName:settings.company_name||'Agence ComTour',address:settings.address,phone:settings.phone,email:settings.email,logoData:await logoDataUrl(),date:new Date().toLocaleDateString('fr-FR'),lines:reportRows.map(r=>({description:`${r.reference||'Mission'} · ${clients.find(c=>c.id===r.client_id)?.full_name||'Client'}`,total:Number(r.estimated_profit_kmf||0)})),summary:[['Missions analysées',String(reportRows.length)],['Rentabilité estimée',money(reportRows.reduce((s,r)=>s+Number(r.estimated_profit_kmf||0),0))],['Coûts ComTour',money(reportRows.reduce((s,r)=>s+Number(r.comtour_costs_kmf||0),0))],['Factures restant à encaisser',String(invoices.filter(i=>i.status!=='payee').length)]],filename:`Rapport-rentabilite-${today()}`})}
  async function closeMission(m:Row){if(!supabase)return;if(m.status==='clôturée'&&role!=='admin'){setNotice('Seul un administrateur peut rouvrir une mission clôturée.');return}const next=m.status==='clôturée'?'en_cours':'clôturée';if(!window.confirm(next==='clôturée'?'Clôturer la mission et figer son bilan financier ?':'Rouvrir cette mission ? La correction sera inscrite dans l’historique.'))return;const {error}=await supabase.from('missions').update({status:next}).eq('id',m.id);if(error)setNotice(error.message);else{await supabase.from('mission_events').insert({mission_id:m.id,event_type:next==='clôturée'?'mission_closed':'mission_reopened',description:`Mission ${next} par ${session.user.email}`});setNotice(`Mission ${next}.`);await loadMission({...m,status:next});await load()}}
  async function printMissionDocument(m:Row){let logoUrl:string|undefined;if(settings.logo_path&&supabase){const {data}=await supabase.storage.from('comtour-documents').createSignedUrl(settings.logo_path,180);logoUrl=data?.signedUrl}printMission(m,settings,logoUrl)}
  async function archiveService(r:Row){if(!supabase)return;if(!window.confirm(r.active?'Archiver ce service ? Il restera dans les devis déjà créés.':'Réactiver ce service ?'))return;const {error}=await supabase.from('catalogue_services').update({active:!r.active}).eq('id',r.id);if(error)setNotice(error.message);else await load()}
  function openNew(){setEditing(null);if(page==='Devis'||page==='Tableau de bord'){if(page==='Tableau de bord')setPage('Devis');setLines([{service_id:'',description:'',quantity:1,unit:'Prestation',unit_price:0,service_fee:0,currency:'KMF',exchange_rate:Number(settings.eur_to_kmf||euroRate)}]);setModal('quote')}else if(page==='Trésorerie')setModal('payment');else if(page==='Paramètres')setModal('settings');else setModal('record')}

  if(!isConfigured)return <Setup/>;
  if(!session)return <main className="auth-shell"><section className="auth-panel"><Brand/><h1>Bienvenue dans votre espace</h1><p>Connectez-vous pour retrouver les opérations de l’Agence ComTour.</p><form onSubmit={login}><label>Adresse e-mail<input name="email" type="email" autoComplete="username" required placeholder="nom@comtour.km"/></label><label>Mot de passe<input name="password" type="password" autoComplete="current-password" required/></label><button className="primary full" disabled={authBusy}>{authBusy?'Connexion…':'Se connecter'}</button></form><div className="secure-note"><ShieldCheck size={16}/> Connexion sécurisée par Supabase</div>{notice&&<p className="notice">{notice}</p>}</section><aside className="auth-art"><div className="island-mark"><Globe2 size={52}/></div><h2>Les voyages qui rapprochent.</h2><p>Votre gestion, au même endroit.</p></aside></main>;

  const clients=all.clients||[],quotes=all.quotes||[],invoices=all.invoices||[],missions=all.missions||[],suppliers=all.suppliers||[],services=(all.catalogue_services||[]).filter(s=>s.active);
  const activeMissions=missions.filter(m=>['confirmée','en_cours','en_preparation'].includes(m.status||''));
  const title=page==='Tableau de bord'?'Bonjour, équipe ComTour.':page;
  const invoiceOutstanding=invoices.reduce((s,i)=>s+Math.max(0,Number(i.amount||0)*Number(i.exchange_rate||1)-(all.payments||[]).filter(p=>p.invoice_id===i.id).reduce((n,p)=>n+Number(p.amount||0)*Number(p.exchange_rate||1)*(p.kind==='remboursement'?-1:1),0)),0);
  const metrics=[['Chiffre d’affaires facturé',money(periodTotals.invoices),CircleDollarSign],['Recettes encaissées',money(periodTotals.payments),ArrowDownLeft],['Trésorerie estimée',money(Number(settings.opening_cash_kmf||0)+totals.cash),Wallet],['Missions actives',String(activeMissions.length),BriefcaseBusiness]] as const;
  return <div className="app-shell">
    <aside className={`sidebar ${mobile?'open':''}`}><Brand/><div className="org-label">Agence de voyages · Moroni<br/>Comores</div><nav aria-label="Navigation principale">{nav.map(item=><button key={item.name} className={`nav-item ${page===item.name?'active':''}`} onClick={()=>{setPage(item.name);setMobile(false);setSelected(null)}}><item.icon size={19}/><span>{item.name}</span></button>)}</nav><button className={`nav-item settings ${page==='Paramètres'?'active':''}`} onClick={()=>{setPage('Paramètres');setMobile(false)}}><Settings size={19}/><span>Paramètres</span></button><div className="sidebar-foot"><div className="island-line">⌁ &nbsp;⌁</div><span>Moroni · Comores</span><small>Des voyages<br/>qui rapprochent</small></div></aside>
    <main className="main"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMobile(!mobile)} aria-label="Menu"><Menu/></button><div className="searchbox"><Search size={17}/><input aria-label="Rechercher" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher dans ce module…"/></div><div className="top-actions"><button className="icon-button" aria-label="Notifications"><Bell size={19}/></button><span className="top-divider"/><button className="profile" onClick={()=>supabase?.auth.signOut()}><span className="avatar">{session.user.email?.slice(0,2).toUpperCase()}</span><span className="profile-name">{session.user.email}</span><LogOut size={16}/></button></div></header>
    <div className="content">{upgradePending&&<div className="upgrade-banner" role="status"><div><b>Activation Supabase à terminer</b><span>Les devis détaillés, suppléments, pièces jointes et bilans de mission ont besoin de la nouvelle migration. Les fiches déjà disponibles restent consultables.</span></div><a href="https://github.com/kevinhadad36/comtour-gestion/blob/main/supabase/migrations/20261101_workflows_finance.sql" target="_blank" rel="noreferrer">Ouvrir le script SQL</a></div>}<div className="heading-row"><div><h1>{title}</h1><p>{page==='Tableau de bord'?'Votre activité ComTour en un coup d’œil.':'Consultez et gérez les données de votre agence.'}</p></div><div className="heading-actions">{page==='Tableau de bord'&&<select className="period" value={period} onChange={e=>setPeriod(e.target.value)}><option value="day">Aujourd’hui</option><option value="week">Cette semaine</option><option value="month">Ce mois</option><option value="quarter">Ce trimestre</option><option value="year">Cette année</option></select>}{(tableByPage[page]||page==='Tableau de bord')&&<button className="primary" onClick={openNew}><Plus size={18}/>{page==='Clients'?'Nouveau client':page==='Catalogue'?'Nouveau service':page==='Charges'?'Programmer une charge':page==='Dépenses'?'Ajouter une dépense':page==='Missions'?'Nouvelle mission':page==='Trésorerie'?'Enregistrer un paiement':'Nouveau devis'}</button>}{page==='Rapports'&&<button className="primary" onClick={()=>downloadCsv(reportRows,'bilan-missions-comtour.csv')}><Download size={17}/>Export Excel / CSV</button>}</div></div>

      {page==='Tableau de bord'&&<><section className="metrics">{metrics.map(([label,value,Icon])=><article className="metric" key={label}><div className="metric-top"><Icon size={20}/><span>{label}</span></div><strong>{value}</strong><small>{label==='Missions actives'?`${missions.length} dossiers au total`:label==='Trésorerie estimée'?'Solde de départ + mouvements enregistrés':`Depuis le début de la période choisie`}</small></article>)}</section><div className="dashboard-grid"><section className="panel chart-panel"><div className="panel-head"><div><h2>Situation financière</h2><p>Évolution mensuelle · KMF convertis selon le taux enregistré</p></div><button className="text-button" onClick={()=>window.print()}><Printer size={15}/> Imprimer</button></div><div className="finance-summary"><div><span>Créances factures estimées</span><b>{money(Math.max(0,invoiceOutstanding))}</b></div><div><span>Dépenses de la période</span><b>{money(periodTotals.expenses)}</b></div><div><span>Résultat de trésorerie enregistré</span><b>{money(Number(settings.opening_cash_kmf||0)+totals.cash)}</b></div></div><div className="real-chart" role="img" aria-label="Évolution réelle des factures, recettes et dépenses sur six mois">{monthlySeries.map(m=><div className="real-chart-month" key={m.label}><div className="real-bars"><i className="billed" style={{height:`${Math.max(2,m.invoices/chartMax*100)}%`}}/><i className="received" style={{height:`${Math.max(2,m.payments/chartMax*100)}%`}}/><i className="spent" style={{height:`${Math.max(2,m.expenses/chartMax*100)}%`}}/></div><small>{m.label}</small></div>)}</div><div className="chart-legend"><span><i className="billed"/>Facturé</span><span><i className="received"/>Encaissé</span><span><i className="spent"/>Dépensé</span></div></section><section className="panel upcoming"><div className="panel-head"><div><h2>À suivre</h2><p>Éléments à traiter</p></div></div>{[['Devis',quotes.filter(q=>['brouillon','envoyé','en_attente'].includes(q.status)).length],['Factures impayées',invoices.filter(i=>i.status!=='payee').length],['Missions actives',activeMissions.length]].map(([label,count])=><button className="todo-row" key={label} onClick={()=>setPage(label==='Devis'?'Devis':label==='Missions actives'?'Missions':'Factures')}><span className="todo-icon"><FileText size={18}/></span><div><b>{label}</b><small>Ouvrir le suivi</small></div><strong>{count}</strong></button>)}</section></div><section className="panel recent"><div className="panel-head"><div><h2>Missions à venir</h2><p>Les dossiers enregistrés dans Supabase</p></div><button className="text-button" onClick={()=>setPage('Missions')}>Toutes les missions</button></div><DataTable rows={activeMissions.slice(0,5)} page="Missions" loading={loading} onSelect={loadMission}/></section></>}

      {tableByPage[page]&&<section className="panel list-panel"><div className="list-toolbar"><div><b>{filtered.length} élément{filtered.length>1?'s':''}</b><small> · Liste liée aux enregistrements de l’agence</small></div><button className="filter-button" onClick={()=>setSearch('')}><X size={15}/>Réinitialiser</button></div><DataTable rows={filtered} page={page} loading={loading} onEdit={r=>{setEditing(r);setModal(page==='Devis'?'quote':'record')}} onAction={async(r,action)=>{
        if(page==='Catalogue')return archiveService(r);
        if(page==='Devis'){if(action==='valider')return updateQuoteStatus(r,'validé');if(action==='facture')return invoiceFromQuote(r);if(action==='acompte')return invoiceFromQuote(r,'acompte');if(action==='mission')return missionFromQuote(r);if(action==='download')return downloadDocument(r,'DEVIS');if(action==='pdf')return printDocument(r,'DEVIS')}
        if(page==='Factures'){if(action==='payer'){setSelected(r);setModal('payment')}if(action==='download')return downloadDocument(r,'FACTURE');if(action==='pdf')return printDocument(r,'FACTURE')}
        if(page==='Missions')return loadMission(r);
        if(page==='Dépenses'&&action==='justificatif'&&supabase&&r.receipt_path){const {data,error}=await supabase.storage.from('comtour-documents').createSignedUrl(r.receipt_path,180);if(error)setNotice(error.message);else window.open(data.signedUrl,'_blank','noopener,noreferrer')}
        if((page==='Clients'||page==='Prestataires')&&action==='historique')return openDirectoryRecord(r);
        if(page==='Trésorerie'&&action==='downloadRecu')return downloadReceipt(r,all.invoices?.find(i=>i.id===r.invoice_id));if(page==='Trésorerie'&&action==='recu'){const {data:logo}=settings.logo_path&&supabase?await supabase.storage.from('comtour-documents').createSignedUrl(settings.logo_path,180):{data:null};return printReceipt(r,all.invoices?.find(i=>i.id===r.invoice_id),settings,logo?.signedUrl)}
      }}/></section>}

      {page==='Rapports'&&<><div className="metrics"><article className="metric"><div className="metric-top"><CircleDollarSign size={19}/><span>Rentabilité calculée</span></div><strong>{money(reportRows.reduce((s,r)=>s+Number(r.estimated_profit_kmf||0),0))}</strong><small>Somme des résultats estimés des missions</small></article><article className="metric"><div className="metric-top"><BriefcaseBusiness size={19}/><span>Missions analysées</span></div><strong>{reportRows.length}</strong><small>Depuis la vue financière Supabase</small></article><article className="metric"><div className="metric-top"><Wallet size={19}/><span>Factures impayées</span></div><strong>{invoices.filter(i=>i.status!=='payee').length}</strong><small>Factures non soldées</small></article><article className="metric"><div className="metric-top"><ArrowUpRight size={19}/><span>Dépenses mission</span></div><strong>{money(reportRows.reduce((s,r)=>s+Number(r.comtour_costs_kmf||0),0))}</strong><small>Coûts ComTour en KMF</small></article></div><section className="panel list-panel"><div className="panel-head report-head"><div><h2>Rentabilité par mission</h2><p>Les avances client sont isolées des coûts ComTour.</p></div><div className="action-group"><button className="filter-button" onClick={downloadReportPdf}><Download size={15}/>Télécharger PDF</button><button className="filter-button" onClick={()=>window.print()}><Printer size={15}/>Imprimer</button></div></div><DataTable rows={reportRows} page="Rapports" loading={loading}/></section><section className="panel list-panel report-head"><h2>Factures restant à encaisser</h2><DataTable rows={invoices.filter(i=>i.status!=='payee')} page="Factures" loading={loading}/></section>{['admin','comptable'].includes(role)&&<section className="panel list-panel audit-panel"><div className="panel-head"><div><h2>Journal des opérations</h2><p>100 dernières créations, modifications et suppressions · réservé aux profils habilités</p></div></div>{auditRows.length===0?<Empty label="Aucune opération enregistrée"/>:<div className="audit-list">{auditRows.map(a=><article className="audit-entry" key={a.id}><time>{new Date(a.occurred_at).toLocaleString('fr-FR')}</time><b>{a.action} · {a.table_name}</b><span>Enregistrement {String(a.row_id).slice(0,8)} · utilisateur {String(a.actor||'système').slice(0,8)}</span></article>)}</div>}</section>}</>}

      {page==='Paramètres'&&<section className="panel settings-panel"><h2>Identité et règles commerciales</h2><p>Ces informations sont réutilisées dans les devis, factures et reçus.</p><div className="settings-grid">{[['Entreprise',settings.company_name],['Adresse',settings.address],['Téléphone',settings.phone||'À renseigner'],['E-mail',settings.email||'À renseigner'],['Taux EUR → KMF',settings.eur_to_kmf],['Clause de prestations supplémentaires','Modifiable par l’administrateur']].map(([k,v])=><div key={k}><small>{k}</small><b>{v}</b></div>)}</div>{role==='admin'&&<button className="primary" onClick={()=>setModal('settings')}><Settings size={16}/>Modifier les paramètres</button>}{role!=='admin'&&<p>Seul le profil administrateur peut modifier ces informations. Profil actuel : {role}.</p>}</section>}

      {selected&&page==='Missions'&&<section className="panel mission-detail"><div className="panel-head"><div><h2>Mission {selected.reference}</h2><p>{selected.destination||'Destination à préciser'} · {selected.status}</p></div><button className="icon-button" aria-label="Fermer la fiche mission" onClick={()=>setSelected(null)}><X/></button></div><div className="metrics compact-metrics">{[['Montant commercial',money(selected.summary?.sold_total_kmf)],['Encaissé',money(selected.summary?.collected_kmf)],['Coûts ComTour',money(selected.summary?.comtour_costs_kmf)],['Marge estimée',money(selected.summary?.estimated_profit_kmf)]].map(([k,v])=><article className="metric" key={k}><small>{k}</small><strong>{v}</strong></article>)}</div><div className="mission-actions"><button className="primary" onClick={()=>setModal('supplement')}><Plus size={16}/>Ajouter un supplément</button><button className="secondary" onClick={()=>{setPage('Dépenses');setSelected(null);setNotice('Sélectionne « Ajouter une dépense » et rattache-la à cette mission.')}}><ArrowUpRight size={16}/>Ajouter une dépense</button><button className="secondary" onClick={()=>downloadMissionDocument(selected)}><Download size={16}/>Télécharger PDF</button><button className="secondary" onClick={()=>printMissionDocument(selected)}><Printer size={16}/>Imprimer</button><button className="secondary" onClick={()=>closeMission(selected)}>{selected.status==='clôturée'?'Rouvrir la mission':'Clôturer la mission'}</button></div><h3>Suppléments et modifications</h3>{(selected.adjustments||[]).length===0?<Empty label="Aucun supplément enregistré"/>:<div className="adjustments">{selected.adjustments.map((a:Row)=><div className="adjustment" key={a.id}><div><b>{a.title}</b><small>{a.description} · {money(a.total,a.currency)} · accord : {a.client_status}</small></div><div className="action-group">{a.client_status==='à_valider'&&<><button className="text-button" onClick={()=>setSupplementStatus(a,'accepté')}><Check size={14}/> Accord reçu</button><button className="text-button danger" onClick={()=>setSupplementStatus(a,'refusé')}>Refuser</button></>}{a.client_status==='accepté'&&a.kind==='supplement'&&<button className="text-button" onClick={()=>invoiceFromSupplement(a)}>{(all.invoices||[]).some(i=>i.adjustment_id===a.id)?'Facture créée':'Créer facture complémentaire'}</button>}</div></div>)}</div>}<h3>Dépenses de la mission</h3><DataTable rows={selected.missionExpenses||[]} page="Dépenses" loading={false}/><h3>Historique des opérations</h3>{(selected.events||[]).map((e:Row)=><div className="event-row" key={e.id}><span>{new Date(e.occurred_at).toLocaleString('fr-FR')}</span><b>{e.description}</b><small>{e.event_type}</small></div>)}</section>}
      {selected&&page==='Clients'&&<section className="panel mission-detail"><div className="panel-head"><div><h2>{selected.full_name}</h2><p>{selected.email||'—'} · {selected.phone||'—'} · Historique client</p></div><button className="icon-button" aria-label="Fermer l’historique" onClick={()=>setSelected(null)}><X/></button></div><h3>Devis</h3><HistoryList rows={selected.historyQuotes||[]}/><h3>Factures et paiements</h3><HistoryList rows={selected.historyInvoices||[]}/><h3>Missions</h3><HistoryList rows={selected.historyMissions||[]}/><p className="history-summary">{(selected.historyPayments||[]).length} règlement(s) associé(s) · Total encaissé {money((selected.historyPayments||[]).filter((p:Row)=>p.kind!=='remboursement').reduce((s:number,p:Row)=>s+Number(p.amount||0)*Number(p.exchange_rate||1),0))}</p></section>}
      {selected&&page==='Prestataires'&&<section className="panel mission-detail"><div className="panel-head"><div><h2>{selected.name}</h2><p>{selected.service_type||'Prestataire'} · Historique des missions et règlements</p></div><button className="icon-button" aria-label="Fermer l’historique" onClick={()=>setSelected(null)}><X/></button></div><h3>Dépenses associées</h3><HistoryList rows={selected.historyExpenses||[]}/><h3>Paiements fournisseur</h3><HistoryList rows={selected.historyPayments||[]}/></section>}
      <footer className="footer"><span>COMTOUR GESTION</span><span>KMF · Franc comorien · Profil {role}</span></footer>
    </div></main>

    {notice&&<button className="toast" onClick={()=>setNotice('')} role="status">{notice}<X size={15}/></button>}
    {modal&&<Modal title={modal==='quote'?'Nouveau devis':modal==='payment'?'Enregistrer un paiement':modal==='supplement'?'Prestation supplémentaire':modal==='settings'?'Paramètres de l’agence':editing?'Modifier':'Nouvel enregistrement'} close={()=>{setModal(null);setEditing(null)}}>
      {modal==='quote'&&<form onSubmit={saveQuote}><label>Objet du devis<input name="title" required placeholder="Séjour, circuit ou prestation"/></label><label>Client<select name="client_id" required defaultValue=""><option value="" disabled>Choisir un client</option>{clients.map(c=><option key={c.id} value={c.id}>{c.full_name}</option>)}</select></label><div className="field-row"><label>Devise<select name="currency" defaultValue="KMF" onChange={e=>setQuoteCurrency(e.target.value,e.currentTarget.form!)}><option>KMF</option><option>EUR</option></select></label><label>Taux EUR → KMF<input name="exchange_rate" type="number" min="0.000001" step="0.01" defaultValue="1" readOnly/></label><label>Acompte %<input name="deposit_percent" type="number" min="0" max="100" defaultValue="50"/></label></div><h3>Prestations</h3>{lines.map((line,i)=><div className="quote-line" key={i}><label>Depuis le catalogue<select value={line.service_id} onChange={e=>{const s=services.find(x=>x.id===e.target.value);const form=e.currentTarget.form;const currency=String(new FormData(form!).get('currency')||'KMF');const rate=currency==='KMF'?1:Number(settings.eur_to_kmf||euroRate);const price=s?Number(s.price)*(s.currency==='EUR'&&currency==='KMF'?rate:s.currency==='KMF'&&currency==='EUR'?1/rate:1):line.unit_price;setLines(lines.map((it,j)=>j!==i?it:{...it,service_id:e.target.value,description:s?.name||it.description,unit:s?.unit||it.unit,unit_price:Number(price.toFixed(2)),currency,exchange_rate:rate}))}}><option value="">Saisie manuelle</option>{services.map(s=><option key={s.id} value={s.id}>{s.name} · {money(s.price,s.currency)}</option>)}</select></label><label>Désignation<input value={line.description} onChange={e=>setLine(i,{description:e.target.value})} required/></label><div className="field-row"><label>Quantité<input type="number" min="0.01" step="0.01" value={line.quantity} onChange={e=>setLine(i,{quantity:Number(e.target.value)})}/></label><label>Unité<input value={line.unit} onChange={e=>setLine(i,{unit:e.target.value})}/></label><label>Prix unitaire<input type="number" min="0" step="0.01" value={line.unit_price} onChange={e=>setLine(i,{unit_price:Number(e.target.value)})}/></label><label>Frais ComTour<input type="number" min="0" step="0.01" value={line.service_fee} onChange={e=>setLine(i,{service_fee:Number(e.target.value)})}/></label></div><button type="button" className="text-button danger" onClick={()=>setLines(lines.filter((_,j)=>j!==i))} disabled={lines.length===1}>Retirer cette ligne</button></div>)}<button type="button" className="secondary" onClick={()=>setLines([...lines,{service_id:'',description:'',quantity:1,unit:'Prestation',unit_price:0,service_fee:0,currency:'KMF',exchange_rate:1}])}><Plus size={15}/>Ajouter une prestation</button><div className="quote-total">Total : <b>{money(lines.reduce((s,l)=>s+l.quantity*l.unit_price+l.service_fee,0),lines[0]?.currency||'KMF')}</b><small>Acompte demandé : 50 % par défaut · La devise suit le devis.</small></div><div className="modal-actions"><button className="secondary" type="button" onClick={()=>setModal(null)}>Annuler</button><button className="primary">Créer le devis</button></div></form>}
      {modal==='record'&&<RecordForm page={page} editing={editing} all={all} settings={settings} submit={saveRecord} cancel={()=>setModal(null)}/>}
      {modal==='payment'&&<form onSubmit={savePayment}><label>Facture<select name="invoice_id" defaultValue={page==='Factures'?selected?.id||'':''}><option value="">Paiement non lié</option>{invoices.map(i=><option key={i.id} value={i.id}>{i.reference} · {money(i.amount,i.currency)}</option>)}</select></label><label>Mission<select name="mission_id" defaultValue={page==='Missions'?selected?.id||'':''}><option value="">Aucune mission</option>{missions.map(m=><option key={m.id} value={m.id}>{m.reference} · {m.destination||'à préciser'}</option>)}</select></label><label>Nature<select name="kind"><option value="encaissement">Encaissement client</option><option value="remboursement">Remboursement client</option><option value="avance_client">Avance reçue</option><option value="paiement_fournisseur">Paiement fournisseur</option></select></label><label>Prestataire (pour un paiement fournisseur)<select name="supplier_id"><option value="">Aucun / sélectionner…</option>{suppliers.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><div className="field-row"><label>Montant<input name="amount" type="number" required min="0.01" step="0.01"/></label><label>Devise<select name="currency"><option>KMF</option><option>EUR</option></select></label><label>Taux EUR → KMF<input name="exchange_rate" type="number" step="0.01" defaultValue={settings.eur_to_kmf||euroRate}/></label></div><div className="field-row"><label>Date<input name="paid_at" type="date" defaultValue={today()}/></label><label>Mode de paiement<select name="method"><option>Espèces</option><option>Virement</option><option>Mobile money</option><option>Carte</option><option>Autre</option></select></label></div><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Annuler</button><button className="primary">Enregistrer et produire le reçu</button></div></form>}
      {modal==='supplement'&&<form onSubmit={saveSupplement}><p className="form-note">Toute modification est soumise à l’accord du client. Le montant est ajusté après validation.</p><label>Type de modification<select name="kind"><option value="supplement">Prestation supplémentaire</option><option value="reduction">Réduction</option><option value="annulation">Annulation</option><option value="remboursement">Remboursement</option></select></label><label>Prestation<select name="service_id" onChange={e=>{const s=services.find(x=>x.id===e.target.value);if(s){const form=e.currentTarget.form;form?.querySelector<HTMLInputElement>('[name=title]')&&((form.querySelector('[name=title]') as HTMLInputElement).value=s.name);form?.querySelector<HTMLInputElement>('[name=unit_price]')&&((form.querySelector('[name=unit_price]') as HTMLInputElement).value=String(s.price))}}}><option value="">Autre prestation</option>{services.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Désignation<input name="title" required/></label><label>Description<textarea name="description" rows={2}/></label><div className="field-row"><label>Quantité<input name="quantity" type="number" min="0.01" step="0.01" defaultValue="1"/></label><label>Prix unitaire<input name="unit_price" type="number" min="0" step="0.01" required/></label><label>Frais ComTour<input name="service_fee" type="number" min="0" step="0.01" defaultValue="0"/></label></div><div className="field-row"><label>Devise<select name="currency"><option>KMF</option><option>EUR</option></select></label><label>Taux EUR → KMF<input name="exchange_rate" type="number" step="0.01" defaultValue={settings.eur_to_kmf||euroRate}/></label></div><label>Motif<input name="reason" defaultValue="Demande complémentaire du client"/></label><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Annuler</button><button className="primary">Soumettre à l’accord client</button></div></form>}
      {modal==='settings'&&<form onSubmit={saveSettings}><label>Nom de l’agence<input name="company_name" defaultValue={settings.company_name}/></label><label>Adresse<input name="address" defaultValue={settings.address}/></label><div className="field-row"><label>Téléphone<input name="phone" defaultValue={settings.phone}/></label><label>E-mail<input name="email" type="email" defaultValue={settings.email}/></label></div><label>Logo de l’agence (PNG, JPEG ou SVG)<input name="logo_file" type="file" accept="image/png,image/jpeg,image/webp"/></label><div className="field-row"><label>Taux manuel EUR → KMF<input name="eur_to_kmf" type="number" min="0.000001" step="0.01" defaultValue={settings.eur_to_kmf||euroRate}/></label><label>Trésorerie de départ (KMF)<input name="opening_cash_kmf" type="number" step="1" defaultValue={settings.opening_cash_kmf||0}/></label></div><label>Clause commerciale<textarea name="service_clause" rows={7} defaultValue={settings.service_clause||clauseDefault}/></label><div className="modal-actions"><button type="button" className="secondary" onClick={()=>setModal(null)}>Annuler</button><button className="primary">Enregistrer</button></div></form>}
    </Modal>}
  </div>;

  function setLine(index:number,patch:Partial<Line>){setLines(prev=>prev.map((l,i)=>i===index?{...l,...patch}:l))}
  function setQuoteCurrency(currency:string,form:HTMLFormElement){const rate=Number(settings.eur_to_kmf||euroRate);setLines(prev=>prev.map(l=>{if(l.currency===currency)return {...l,exchange_rate:currency==='KMF'?1:rate};const factor=currency==='EUR'?1/rate:rate;return {...l,unit_price:Number((l.unit_price*factor).toFixed(2)),service_fee:Number((l.service_fee*factor).toFixed(2)),currency,exchange_rate:currency==='KMF'?1:rate}}));const fx=form.querySelector<HTMLInputElement>('[name=exchange_rate]');if(fx)fx.value=String(currency==='KMF'?1:rate)}
}

function DataTable({rows,page,loading,onEdit,onAction,onSelect}:{rows:Row[];page:Page|'Rapports';loading:boolean;onEdit?:(r:Row)=>void;onAction?:(r:Row,action:string)=>void;onSelect?:(r:Row)=>void}){
  if(loading)return <div className="empty-state">Chargement des données…</div>;
  if(!rows.length)return <Empty label="Aucun élément pour le moment" detail="Créez une première fiche pour commencer le suivi."/>;
  const cols=page==='Clients'?['Client','E-mail','Téléphone']:page==='Missions'?['Référence','Destination','Début','Statut']:page==='Catalogue'?['Service','Catégorie','Tarif par','Prix','État']:page==='Dépenses'?['Description','Catégorie','Date','Montant','Nature']:page==='Trésorerie'?['Reçu','Nature','Date','Montant','Mode']:page==='Rapports'?['Mission','Vente KMF','Encaissé','Coûts ComTour','Marge']:page==='Charges'?['Charge','Catégorie','Montant','Échéance','État']:['Référence','Désignation','Statut','Montant','Devise'];
  return <div className="table-wrap"><table><thead><tr>{cols.map(c=><th key={c}>{c}</th>)}<th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} onDoubleClick={()=>onSelect?.(r)}>{page==='Clients'?<><td><b>{r.full_name}</b></td><td>{r.email||'—'}</td><td>{r.phone||'—'}</td></>:page==='Missions'?<><td><b>{r.reference}</b></td><td>{r.destination||'—'}</td><td>{r.start_date||'—'}</td><td><Status value={r.status}/></td></>:page==='Catalogue'?<><td><b>{r.name}</b><small className="service-description">{r.description}</small></td><td>{r.category}</td><td>{r.unit}</td><td>{money(r.price,r.currency)}</td><td>{r.active?'Actif':'Archivé'}</td></>:page==='Dépenses'?<><td>{r.description}</td><td>{r.category}</td><td>{r.paid_at}</td><td>{money(r.amount,r.currency)}</td><td>{r.payer}</td></>:page==='Trésorerie'?<><td>{r.receipt_reference||'—'}</td><td>{r.kind}</td><td>{r.paid_at}</td><td>{money(r.amount,r.currency)}</td><td>{r.method||'—'}</td></>:page==='Rapports'?<><td>{r.reference}</td><td>{money(r.sold_total_kmf)}</td><td>{money(r.collected_kmf)}</td><td>{money(r.comtour_costs_kmf)}</td><td>{money(r.estimated_profit_kmf)}</td></>:page==='Charges'?<><td>{r.title}</td><td>{r.category}</td><td>{money(r.amount,r.currency)}</td><td>Le {r.due_day} de chaque mois</td><td>{r.active?'Active':'Archivée'}</td></>:<><td><b>{r.reference}</b></td><td>{r.title||r.description||r.kind||'—'}</td><td><Status value={r.status||'Enregistré'}/></td><td>{money(r.amount,r.currency)}</td><td>{r.currency||'KMF'}</td></>}
    <td><div className="action-group">{page==='Devis'&&<><button className="text-button" onClick={()=>onAction?.(r,'download')}><Download size={13}/>Télécharger PDF</button><button className="text-button" onClick={()=>onAction?.(r,'pdf')}><Printer size={13}/>Imprimer</button>{r.status!=='validé'&&<button className="text-button" onClick={()=>onAction?.(r,'valider')}>Valider</button>}<button className="text-button" onClick={()=>onAction?.(r,'facture')}>Facture</button><button className="text-button" onClick={()=>onAction?.(r,'acompte')}>Acompte</button><button className="text-button" onClick={()=>onAction?.(r,'solde')}>Solde</button><button className="text-button" onClick={()=>onAction?.(r,'mission')}>Mission</button></>}{page==='Factures'&&<><button className="text-button" onClick={()=>onAction?.(r,'download')}><Download size={13}/>Télécharger PDF</button><button className="text-button" onClick={()=>onAction?.(r,'pdf')}><Printer size={13}/>Imprimer</button><button className="text-button" onClick={()=>onAction?.(r,'payer')}>Paiement</button></>}{page==='Dépenses'&&r.receipt_path&&<button className="text-button" onClick={()=>onAction?.(r,'justificatif')}>Justificatif</button>}{page==='Trésorerie'&&r.receipt_reference&&<><button className="text-button" onClick={()=>onAction?.(r,'downloadRecu')}><Download size={13}/>Télécharger reçu PDF</button><button className="text-button" onClick={()=>onAction?.(r,'recu')}><Printer size={13}/>Imprimer reçu</button></>}{page==='Missions'&&<button className="text-button" onClick={()=>onSelect?.(r)}>Ouvrir le dossier</button>}{page==='Catalogue'&&<button className="text-button" onClick={()=>onAction?.(r,'toggle')}>{r.active?'Archiver':'Réactiver'}</button>}{['Clients','Prestataires'].includes(page)&&<button className="text-button" onClick={()=>onAction?.(r,'historique')}>Historique</button>}{['Clients','Factures','Dépenses','Prestataires','Charges'].includes(page)&&<button className="text-button" onClick={()=>onEdit?.(r)}>Modifier</button>}</div></td></tr>)}</tbody></table></div>;
}
function Status({value}:{value:string}){const cls=String(value||'').toLowerCase().includes('pay')||String(value||'').includes('valid')?'enabled':String(value||'').includes('annul')||String(value||'').includes('refus')?'disabled':'pending';return <span className={`service-state ${cls}`}>{value||'—'}</span>}
function Empty({label,detail=''}:{label:string;detail?:string}){return <div className="empty-state"><div className="empty-icon"><FileText size={22}/></div><b>{label}</b><span>{detail}</span></div>}
function HistoryList({rows}:{rows:Row[]}){if(!rows.length)return <p className="history-empty">Aucun élément associé.</p>;return <div className="history-list">{rows.map(r=><div className="history-entry" key={r.id}><b>{r.reference||r.title||r.description||r.kind||'Opération'}</b><span>{r.status||r.paid_at||r.start_date||r.kind||'—'}</span><strong>{r.amount?money(r.amount,r.currency):'—'}</strong></div>)}</div>}
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="modal modal-wide"><div className="modal-head"><div><h2>{title}</h2><p>Les données sont enregistrées dans l’espace sécurisé de l’agence.</p></div><button className="icon-button" aria-label="Fermer" onClick={close}><X/></button></div>{children}</section></div>}
function RecordForm({page,editing,all,settings,submit,cancel}:{page:Page;editing:Row|null;all:Record<string,Row[]>;settings:Row;submit:(e:FormEvent<HTMLFormElement>)=>void;cancel:()=>void}){
  const fields:Record<string,{key:string;label:string;type?:string;options?:string[];rel?:string;required?:boolean}[]>={
    Clients:[{key:'full_name',label:'Nom / organisation',required:true},{key:'email',label:'E-mail',type:'email'},{key:'phone',label:'Téléphone'},{key:'address',label:'Adresse'},{key:'notes',label:'Notes'}],
    Factures:[{key:'reference',label:'Référence'},{key:'quote_id',label:'Devis',rel:'quotes'},{key:'client_id',label:'Client',rel:'clients'},{key:'kind',label:'Type',options:['standard','acompte','solde','complementaire']},{key:'status',label:'Statut',options:['impayee','partiellement_payee','payee','annulee']},{key:'amount',label:'Montant',type:'number',required:true},{key:'currency',label:'Devise',options:['KMF','EUR']},{key:'exchange_rate',label:'Taux EUR → KMF',type:'number'}],
    Missions:[{key:'reference',label:'Référence'},{key:'quote_id',label:'Devis',rel:'quotes'},{key:'client_id',label:'Client',rel:'clients'},{key:'destination',label:'Destination'},{key:'start_date',label:'Début',type:'date'},{key:'end_date',label:'Fin',type:'date'},{key:'status',label:'Statut',options:['en_preparation','confirmée','en_cours','terminée','clôturée','annulée']}],
    Dépenses:[{key:'description',label:'Description',required:true},{key:'mission_id',label:'Mission',rel:'missions'},{key:'supplier_id',label:'Prestataire',rel:'suppliers'},{key:'category',label:'Catégorie',options:categories},{key:'amount',label:'Montant',type:'number',required:true},{key:'currency',label:'Devise',options:['KMF','EUR']},{key:'exchange_rate',label:'Taux EUR → KMF',type:'number'},{key:'payer',label:'Traitement',options:['comtour','client_advance','client_charge','exceptional']},{key:'paid_at',label:'Date',type:'date'},{key:'is_paid',label:'Dépense payée ?',options:['true','false']},{key:'receipt_file',label:'Justificatif (PDF ou photo)',type:'file'}],
    Prestataires:[{key:'name',label:'Nom du prestataire',required:true},{key:'email',label:'E-mail',type:'email'},{key:'phone',label:'Téléphone'},{key:'address',label:'Adresse'},{key:'service_type',label:'Type de prestation'}],
    Catalogue:[{key:'name',label:'Nom du service',required:true},{key:'category',label:'Catégorie',options:['Hébergement','Excursions touristiques','Randonnées','Circuits touristiques','Transport et transferts','Billets inter-îles','Activités marines','Guides touristiques','Organisation et coordination','Frais de service ComTour','Autres dépenses']},{key:'description',label:'Description'},{key:'unit',label:'Tarif par',options:['Personne','Groupe','Véhicule','Nuit','Prestation']},{key:'price',label:'Prix',type:'number',required:true},{key:'currency',label:'Devise',options:['KMF','EUR']}],
    Charges:[{key:'title',label:'Libellé de la charge',required:true},{key:'category',label:'Catégorie',options:['Loyer','Électricité','Internet','Téléphone','Salaires','Entretien','Communication','Fournitures de bureau','Frais administratifs','Autres']},{key:'amount',label:'Montant mensuel',type:'number',required:true},{key:'currency',label:'Devise',options:['KMF','EUR']},{key:'exchange_rate',label:'Taux EUR → KMF',type:'number'},{key:'due_day',label:'Jour d’échéance',type:'number'},{key:'start_date',label:'Début',type:'date'},{key:'end_date',label:'Fin (facultatif)',type:'date'},{key:'supplier_id',label:'Prestataire',rel:'suppliers'}],
  };
  return <form onSubmit={submit}><div className="form-grid">{(fields[page]||[]).map(f=><label key={f.key} className={['address','notes','description'].includes(f.key)?'span-all':''}>{f.label}{f.options?<select name={f.key} defaultValue={editing?.[f.key]??f.options[0]} required={f.required}>{f.options.map(v=><option key={v} value={v}>{v==='true'?'Oui':v==='false'?'Non':v}</option>)}</select>:f.rel?<select name={f.key} defaultValue={editing?.[f.key]??''}><option value="">Aucun / sélectionner…</option>{(all[f.rel]||[]).map(r=><option key={r.id} value={r.id}>{r.full_name||r.name||r.reference||r.title}</option>)}</select>:<input name={f.key} type={f.type||'text'} defaultValue={editing?.[f.key]??(f.key==='exchange_rate'?settings.eur_to_kmf||euroRate:f.key==='paid_at'||f.key==='start_date'?today():undefined)} min={f.type==='number'?0:undefined} step={f.type==='number'?'0.01':undefined} required={f.required}/>}</label>)}</div><div className="modal-actions"><button type="button" className="secondary" onClick={cancel}>Annuler</button><button className="primary">{editing?'Enregistrer les modifications':'Enregistrer'}</button></div></form>
}
function Brand(){return <div className="brand"><img src={`${import.meta.env.BASE_URL}comtour.svg`} alt=""/><div><b>ComTour</b><small>GESTION</small></div></div>}
function Setup(){return <main className="setup-shell"><section className="setup-card"><Brand/><h1>Configuration Supabase requise</h1><p>La connexion sécurisée n’est pas configurée pour cette version. Ajoute l’URL et la clé publique publishable dans les variables GitHub Actions, puis redéploie.</p><div className="setup-steps"><div><b>1</b><span>VITE_SUPABASE_URL dans les variables du dépôt.</span></div><div><b>2</b><span>VITE_SUPABASE_PUBLISHABLE_KEY dans les secrets GitHub.</span></div><div><b>3</b><span>Les données de démonstration ne s’affichent jamais en production.</span></div></div><p className="security-copy"><ShieldCheck size={18}/> Ne place jamais une clé secrète ou service_role dans le frontend.</p></section></main>}
function printMission(m:Row,settings:Row,logo?:string){const s=m.summary||{};const rows=[['Montant du devis initial',money(s.initial_quote_kmf)],['Modifications acceptées',money(s.accepted_changes_kmf)],['Montant vendu',money(s.sold_total_kmf)],['Recettes encaissées',money(s.collected_kmf)],['Reste à encaisser',money(s.receivable_kmf)],['Coûts supportés par ComTour',money(s.comtour_costs_kmf)],['Avances pour le client',money(s.client_advances_kmf)],['Résultat estimé',money(s.estimated_profit_kmf)]];printHtml(`${settings.company_name||'ComTour'} · Bilan ${m.reference}`,`<header>${logo?`<img class="logo" src="${html(logo)}">`:''}<h1>${html(settings.company_name||'Agence ComTour')}</h1><p>${html(settings.address||'')} · ${html(settings.phone||'')} · ${html(settings.email||'')}</p></header><hr><h2>Bilan financier · ${html(m.reference)}</h2><p>${html(m.destination||'Destination à préciser')} · État : ${html(m.status||'')}</p><table><tbody>${rows.map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</tbody></table><h3>Prestations supplémentaires</h3><table><thead><tr><th>Prestation</th><th>Décision client</th><th>Montant</th></tr></thead><tbody>${(m.adjustments||[]).map((a:Row)=>`<tr><td>${html(a.title)}</td><td>${html(a.client_status)}</td><td>${money(a.total,a.currency)}</td></tr>`).join('')}</tbody></table><footer>Document COMTOUR GESTION · ${new Date().toLocaleDateString('fr-FR')}</footer>`)}
function html(value:unknown){return String(value??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;')}
function printReceipt(payment:Row,invoice:Row|undefined,settings:Row,logo?:string){printHtml(`Reçu ${payment.receipt_reference||'ComTour'}`,`<header>${logo?`<img class="logo" src="${html(logo)}">`:''}<h1>${html(settings.company_name||'Agence ComTour')}</h1><p>${html(settings.address||'Moroni, Grande Comore, Union des Comores')} · ${html(settings.phone||'')} · ${html(settings.email||'')}</p></header><hr><h2>REÇU DE PAIEMENT</h2><p>Référence : ${html(payment.receipt_reference||'REC')}</p><p>Date : ${html(payment.paid_at||today())}</p><p>Facture : ${html(invoice?.reference||'Paiement sans facture liée')}</p><p>Mode : ${html(payment.method||'—')}</p><h2>Montant reçu : ${money(payment.amount,payment.currency)}</h2><p>Nature : ${html(payment.kind)}</p><footer>Reçu généré par COMTOUR GESTION</footer>`)}
function printHtml(title:string,body:string){const w=window.open('','_blank','width=820,height=900');if(!w)return;w.document.write(`<!doctype html><html lang="fr"><head><meta charset="utf-8"><title>${html(title)}</title><style>body{font:14px Arial,sans-serif;color:#152f45;max-width:760px;margin:40px auto;padding:0 24px}header{color:#102d45;border-bottom:2px solid #108c91;padding-bottom:12px}h1{font-size:24px;margin-bottom:6px}h2{margin-top:32px}p{line-height:1.6}.logo{max-width:140px;max-height:56px;object-fit:contain}table{width:100%;border-collapse:collapse;margin:24px 0}td,th{padding:12px;border-bottom:1px solid #dce4e9;text-align:left}td:last-child,th:last-child{text-align:right}td small{display:block;color:#687b8c;margin-top:4px}.total{font-size:20px;text-align:right;font-weight:700}.terms{margin-top:35px;padding-top:12px;border-top:1px solid #dce4e9;font-size:11px;color:#506579}footer{margin-top:70px;color:#657789;border-top:1px solid #ccd6de;padding-top:12px}@media print{body{margin:0 auto}}</style></head><body>${body}<script>window.onload=()=>window.print()</script></body></html>`);w.document.close()}
function downloadCsv(rows:Row[],filename:string){if(!rows.length)return;const headers=Object.keys(rows[0]);const csv=[headers.join(';'),...rows.map(r=>headers.map(h=>`"${String(r[h]??'').replace(/"/g,'""')}"`).join(';'))].join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download=filename;link.click();URL.revokeObjectURL(link.href)}

